create or replace function public.create_event(p_club_id uuid,p_type public.event_type,p_name text,p_venue text,p_starts_at timestamptz,p_ends_at timestamptz,p_capacity integer,p_court_count integer,p_formats text[],p_record_class public.record_class,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_id uuid;begin if not private.has_club_role(p_club_id,array['owner','organizer']::public.club_role[])then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;insert into public.events(club_id,type,name,venue,starts_at,ends_at,capacity,formats,record_class)values(p_club_id,p_type,p_name,p_venue,p_starts_at,p_ends_at,p_capacity,p_formats,p_record_class)returning id into v_id;insert into public.event_courts(event_id,label)select v_id,'Court '||n from generate_series(1,p_court_count)n;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,request_id)values(auth.uid(),'event.created','event',v_id,p_club_id,p_idempotency_key);return v_id;end$$;
create or replace function public.transition_event(p_event_id uuid,p_expected_version bigint,p_transition public.event_status,p_idempotency_key uuid)returns bigint language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_club uuid;v_version bigint;begin select club_id into v_club from public.events where id=p_event_id for update;if not private.has_club_role(v_club,array['owner','organizer']::public.club_role[])then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;update public.events set status=p_transition where id=p_event_id and version=p_expected_version returning version+1 into v_version;if v_version is null then raise exception using errcode='P0001',detail='STALE_VERSION';end if;return v_version;end$$;
create or replace function public.register_for_event(p_event_id uuid,p_terms_version text,p_idempotency_key uuid)returns table(registration_id uuid,status public.registration_status,waitlist_position bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_player uuid:=public.current_player_id();v_capacity int;v_count int;v_status public.registration_status;v_position bigint;begin if v_player is null or not exists(select 1 from public.accounts where player_id=v_player and contact_verified_at is not null)then raise exception using errcode='P0001',detail='PLAYER_NOT_VERIFIED';end if;select capacity into v_capacity from public.events where id=p_event_id and status='published' and(now() between coalesce(registration_opens_at,'-infinity') and coalesce(registration_closes_at,'infinity'))for update;if v_capacity is null then raise exception using errcode='P0001',detail='INVALID_STATE_TRANSITION';end if;select count(*) into v_count from public.event_registrations where event_id=p_event_id and status='confirmed';if v_count<v_capacity then v_status:='confirmed';else v_status:='waitlisted';select coalesce(max(r.waitlist_position),0)+1 into v_position from public.event_registrations r where r.event_id=p_event_id;end if;insert into public.event_registrations(event_id,player_id,status,waitlist_position,terms_version)values(p_event_id,v_player,v_status,v_position,p_terms_version)returning id,public.event_registrations.status,public.event_registrations.waitlist_position into registration_id,status,waitlist_position;return next;exception when unique_violation then raise exception using errcode='P0001',detail='ALREADY_EXISTS';end$$;
create or replace function public.withdraw_from_event(p_event_id uuid,p_reason text,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_id uuid;begin update public.event_registrations set status='withdrawn',withdrawn_at=now(),version=version+1 where event_id=p_event_id and player_id=public.current_player_id() and status in('confirmed','waitlisted')returning id into v_id;if v_id is null then raise exception using errcode='P0001',detail='NOT_FOUND';end if;with promoted as(select id from public.event_registrations where event_id=p_event_id and status='waitlisted' order by waitlist_position for update skip locked limit 1)update public.event_registrations r set status='confirmed',waitlist_position=null from promoted where r.id=promoted.id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id,after_state)values(auth.uid(),'registration.withdrawn','registration',v_id,p_idempotency_key,jsonb_build_object('reason',p_reason));return v_id;end$$;
revoke all on function public.create_event(uuid,public.event_type,text,text,timestamptz,timestamptz,integer,integer,text[],public.record_class,uuid),public.transition_event(uuid,bigint,public.event_status,uuid),public.register_for_event(uuid,text,uuid),public.withdraw_from_event(uuid,text,uuid)from public;grant execute on function public.create_event(uuid,public.event_type,text,text,timestamptz,timestamptz,integer,integer,text[],public.record_class,uuid),public.transition_event(uuid,bigint,public.event_status,uuid),public.register_for_event(uuid,text,uuid),public.withdraw_from_event(uuid,text,uuid)to authenticated;
